import{_ as t,a0 as l,w as d,s as p,ao as i,I as n,x as o,a1 as a,A as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"如何在雲服務提供商的平台上使用Docker Machine | LCTT x X-CMD","titleTemplate":false,"description":"如何在雲服務提供商的平台上使用Docker Machine | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在雲服務提供商的平台上使用Docker Machine | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在雲服務提供商的平台上使用Docker Machine | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150520 How to Use Docker Machine with a Cloud Provider","title":"如何在雲服務提供商的平台上使用Docker Machine","tag":"201506","desc":""},"relativePath":"201506/20150520 How to Use Docker Machine with a Cloud Provider.md","filePath":"[post].md"}'),h={name:"201506/20150520 How to Use Docker Machine with a Cloud Provider.md"};function k(s,e,m,u,g,D){const r=l("Link");return d(),p("div",null,[e[16]||(e[16]=i(`<h1 id="如何在雲服務提供商的平台上使用docker-machine" tabindex="-1">如何在雲服務提供商的平台上使用Docker Machine <a class="header-anchor" href="#如何在雲服務提供商的平台上使用docker-machine" aria-label="Permalink to “如何在雲服務提供商的平台上使用Docker Machine”">​</a></h1><p>大家好，今天我們來了解如何使用Docker Machine在各種雲服務提供商的平台上部署Docker。Docker Machine是一個可以幫助我們在自己的電腦、雲服務提供商的平台以及我們數據中心的機器上創建Docker機器的應用程序。它為創建服務器、在服務器中安裝Docker、根據用户需求配置Docker客户端提供了簡單的解決方案。驅動API對本地機器、數據中心的虛擬機或者公用雲機器都適用。Docker Machine支持Windows、OSX和Linux，並且提供一個獨立的二進制文件，可以直接使用。它讓我們可以充分利用支持Docker的基礎設施的生態環境合作伙伴，並且使用相同的接口進行訪問。它讓人們可以使用一個命令來簡單而迅速地在不同的雲平台部署Docker容器。</p><h3 id="_1-安裝docker-machine" tabindex="-1">1. 安裝Docker Machine <a class="header-anchor" href="#_1-安裝docker-machine" aria-label="Permalink to “1. 安裝Docker Machine”">​</a></h3><p>Docker Machine可以很好地支持每一種Linux發行版。首先，我們需要從Github網站下載最新版本的。這裏我們使用curl來下載目前最新0.2.0版本的Docker Machine。</p><p>在64位操作系統運行：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-amd64 &gt; /usr/local/bin/docker-machine
</code></pre><p>在32位操作系統運行：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-i386 &gt; /usr/local/bin/docker-machine
</code></pre><p>下載最新版本的Docker Machine並將docker-machine文件放到了/usr/local/bin/後，添加執行權限：</p><pre><code># chmod +x /usr/local/bin/docker-machine
</code></pre><p>完成如上操作後，我們需要確認已經成功安裝docker-machine了。可以運行如下命令檢查，它會輸出系統中docker-machine的版本：</p><pre><code># docker-machine -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/installing-docker-machine.png" alt="Installing Docker Machine"></p><p>要在我們的機器上啓用docker命令，需要使用如下命令安裝Docker客户端：</p><pre><code>    # curl -L https://get.docker.com/builds/linux/x86_64/docker-latest &gt; /usr/local/bin/docker
    # chmod +x /usr/local/bin/docker
</code></pre><h3 id="_2-創建機器" tabindex="-1">2. 創建機器 <a class="header-anchor" href="#_2-創建機器" aria-label="Permalink to “2. 創建機器”">​</a></h3>`,16)),n("p",null,[e[1]||(e[1]=o("在自己的Linux機器上安裝好了Docker Machine之後，我們想要將一個docker虛擬機部署到雲服務器上。Docker Machine支持幾個流行的雲平台，如igital Ocean、Amazon Web Services（AWS）、Microsoft Azure、Google Cloud Computing及其它等等，所以我們可以在不同的平台使用相同的接口來部署Docker。本文中我們會使用digitalocean驅動在Digital Ocean的服務器上部署Docker，--driver選項指定digitalocean驅動，--digitalocean-access-token選項指定",-1)),a(r,{href:"https://cloud.digitalocean.com/settings/applications"},{default:c(()=>[...e[0]||(e[0]=[o("Digital Ocean Control Panel",-1)])]),_:1}),e[2]||(e[2]=o("提供的API Token，命令最後的是我們創建的Docker虛擬機的機器名。運行如下命令：",-1))]),e[17]||(e[17]=i(`<pre><code># docker-machine create --driver digitalocean --digitalocean-access-token &lt;API-Token&gt; linux-dev

# eval &quot;$(docker-machine env linux-dev)&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-digitalocean-cloud.png" alt="Docker Machine Digitalocean Cloud"></p><p><strong>注意</strong>： 這裏linux-dev是我們將要創建的機器的名稱。<code>&lt;API-Token&gt;</code>是一個安全key，可以在Digtal Ocean Control Panel生成。要找到這個key，我們只需要登錄到我們的Digital Ocean Control Panel，然後點擊API，再點擊 Generate New Token，填寫一個名稱，選上Read和Write。然後我們就會得到一串十六進制的key，那就是<code>&lt;API-Token&gt;</code>，簡單地替換到上邊的命令中即可。</p><p>運行如上命令後，我們可以在Digital Ocean Droplet Panel中看到一個具有默認配置的droplet已經被創建出來了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/digitalocean-droplet-panel.png" alt="DigitalOcean Droplet Panel"></p><p>簡便起見，docker-machine會使用默認配置來部署Droplet。我們可以通過增加選項來定製我們的Droplet。這裏是一些digitalocean相關的選項，我們可以使用它們來覆蓋Docker Machine所使用的默認配置。</p><ul><li>--digitalocean-image &quot;ubuntu-14-04-x64&quot; 用於選擇Droplet的鏡像</li><li>--digitalocean-ipv6 enable 啓用IPv6網絡支持</li><li>--digitalocean-private-networking enable 啓用專用網絡</li><li>--digitalocean-region &quot;nyc3&quot; 選擇部署Droplet的區域</li><li>--digitalocean-size &quot;512mb&quot; 選擇內存大小和部署的類型</li></ul><p>如果你想在其他雲服務使用docker-machine，並且想覆蓋默認的配置，可以運行如下命令來獲取Docker Mackine默認支持的對每種平台適用的參數。</p><pre><code># docker-machine create -h
</code></pre><h3 id="_3-選擇活躍主機" tabindex="-1">3. 選擇活躍主機 <a class="header-anchor" href="#_3-選擇活躍主機" aria-label="Permalink to “3. 選擇活躍主機”">​</a></h3><p>部署Droplet後，我們想馬上運行一個Docker容器，但在那之前，我們需要檢查下活躍主機是否是我們需要的機器。可以運行如下命令查看。</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-ls.png" alt="Docker Machine List"></p><p>ACTIVE一列有“*”標記的是活躍主機。</p><p>現在，如果我們想將活躍主機切換到需要的主機，運行如下命令：</p><pre><code># docker-machine active linux-dev
</code></pre><p><strong>注意</strong>：這裏，linux-dev是機器名，我們打算激活這個機器，並且在其上運行Docker容器。</p><h3 id="_4-運行一個docker容器" tabindex="-1">4. 運行一個Docker容器 <a class="header-anchor" href="#_4-運行一個docker容器" aria-label="Permalink to “4. 運行一個Docker容器”">​</a></h3><p>現在，我們已經選擇了活躍主機，就可以運行Docker容器了。可以測試一下，運行一個busybox容器來執行<code>echo hello word</code>命令，這樣就可以得到輸出：</p><pre><code># docker run busybox echo hello world
</code></pre><p>注意：如果你試圖在一個裝有32位操作系統的宿主機部署Docker容器，使用SSH來運行docker是個好辦法。這樣你就可以簡單跳過這一步，直接進入下一步。</p><h3 id="_5-ssh到docker機器中" tabindex="-1">5. SSH到Docker機器中 <a class="header-anchor" href="#_5-ssh到docker機器中" aria-label="Permalink to “5. SSH到Docker機器中”">​</a></h3><p>如果我們想在機器或者Droplet上控制之前部署的Docker機器，可以使用docker-machine ssh命令來SSH到機器上：</p><pre><code># docker-machine ssh
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-ssh.png" alt="Docker Machine SSH"></p><p>SSH到機器上之後，我們可以在上邊運行任何Docker容器。這裏我們運行一個nginx：</p><pre><code># docker run -itd -p 80:80 nginx
</code></pre><p>操作完畢後，我們需要運行exit命令來退出Droplet或者服務器。</p><pre><code># exit
</code></pre><h3 id="_5-刪除主機" tabindex="-1">5. 刪除主機 <a class="header-anchor" href="#_5-刪除主機" aria-label="Permalink to “5. 刪除主機”">​</a></h3><p>刪除在運行的主機以及它的所有鏡像和容器，我們可以使用docker-machine rm命令：</p><pre><code># docker-machine rm linux-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-remove-machine.png" alt="Docker Machine Remove All"></p><p>使用docker-machine ls命令檢查是否成功刪除了：</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-remove-check.png" alt="Docker Machine Remove Check"></p><h3 id="_6-在不使用驅動的情況新增一個主機" tabindex="-1">6. 在不使用驅動的情況新增一個主機 <a class="header-anchor" href="#_6-在不使用驅動的情況新增一個主機" aria-label="Permalink to “6. 在不使用驅動的情況新增一個主機”">​</a></h3><p>我們可以在不使用驅動的情況往Docker增加一台主機，只需要一個URL。它可以使用一個已有機器的別名，所以我們就不需要每次在運行docker命令時輸入完整的URL了。</p><pre><code>$ docker-machine create --url=tcp://104.131.50.36:2376 custombox
</code></pre><h3 id="_7-管理主機" tabindex="-1">7. 管理主機 <a class="header-anchor" href="#_7-管理主機" aria-label="Permalink to “7. 管理主機”">​</a></h3><p>如果你已經讓Docker運行起來了，可以使用簡單的<strong>docker-machine stop</strong>命令來停止所有正在運行的主機，如果需要再啓動的話可以運行<strong>docker-machine start</strong>：</p><pre><code># docker-machine stop
# docker-machine start
</code></pre><p>你也可以使用如下命令來使用機器名作為參數來將其停止或啓動：</p><pre><code>$ docker-machine stop linux-dev
$ docker-machine start linux-dev
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Docker Machine是一個非常棒的工具，可以使用Docker容器快速地部署服務。文中我們使用Digital Ocean Platform作演示，但Docker Machine還支持其他平台，如Amazon Web Service、Google Cloud Computing。使用Docker Machine，快速、安全地在幾種不同平台部署Docker容器變得很簡單了。因為Docker Machine還是Beta版本，不建議在生產環境使用。如果你有任何問題、建議、反饋，請在下方的評論框中寫下來，我們會改進或者更新我們的內容。謝謝！享受吧 😃</p><hr>`,47)),n("p",null,[e[4]||(e[4]=o("via: ",-1)),a(r,{href:"http://linoxide.com/linux-how-to/use-docker-machine-cloud-provider/"},{default:c(()=>[...e[3]||(e[3]=[o("http://linoxide.com/linux-how-to/use-docker-machine-cloud-provider/",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=o("作者：",-1)),a(r,{href:"http://linoxide.com/author/arunp/"},{default:c(()=>[...e[5]||(e[5]=[o("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=o(" 譯者：",-1)),a(r,{href:"https://github.com/goreliu"},{default:c(()=>[...e[6]||(e[6]=[o("goreliu",-1)])]),_:1}),e[10]||(e[10]=o(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:c(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=o("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:c(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原創翻譯，",-1)),a(r,{href:"https://linux.cn/"},{default:c(()=>[...e[12]||(e[12]=[o("Linux中國",-1)])]),_:1}),e[15]||(e[15]=o(" 榮譽推出",-1))])])}const _=t(h,[["render",k]]);export{M as __pageData,_ as default};
